package com.acrenex.app.activities;
import android.os.Bundle;import android.graphics.Color;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.acrenex.app.utils;
public class WorkflowActivity extends AppCompatActivity{@Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=utils.screen(this,"Workflow","How a land service moves across departments.");String[] steps={"1. Citizen submits application","2. Identity and proof verification","3. Revenue / registration review","4. Parcel and document checks","5. Department decision","6. Citizen receives status update"};for(String s:steps){LinearLayout box=utils.column(this);box.addView(utils.text(this,s,16,Color.rgb(24,59,86),true));utils.addCard(root,box,this);}utils.setScreenContentView(this, root);}}
